def fuse(lists: list[list[int]], k: int = 60) -> list[int]:
    score: dict[int, float] = {}
    for ranked in lists:
        for rank, cid in enumerate(ranked, start=1):
            score[cid] = score.get(cid, 0) + 1 / (k + rank)
    return sorted(score, key=score.get, reverse=True)
